Script:
Write-Output "Configuring IIS HTTPS binding..."

$lookupMode = ([string]$Jaws.Parameters["STEP.CertificateLookupMode"].Value).Trim()
$storeName = ([string]$Jaws.Parameters["STEP.CertificateStoreName"].Value).Trim()
$siteName = ([string]$Jaws.Parameters["STEP.WebsiteName"].Value).Trim()
$hostName = ([string]$Jaws.Parameters["STEP.BindingHostName"].Value).Trim()
$requireSni = [System.Convert]::ToBoolean(
  $Jaws.Parameters["STEP.RequireSni"].Value
)

if ([string]::IsNullOrWhiteSpace($storeName)) {
  throw "Certificate store name is required."
}

if ([string]::IsNullOrWhiteSpace($siteName)) {
  throw "Website name is required."
}

if ([string]::IsNullOrWhiteSpace($hostName)) {
  throw "Binding host name is required."
}

$administrationAssembly =
  Join-Path $env:windir "System32\inetsrv\Microsoft.Web.Administration.dll"

if (-not (Test-Path -LiteralPath $administrationAssembly)) {
  throw "Microsoft.Web.Administration.dll was not found. Verify that IIS is installed."
}

if ($null -eq ("Microsoft.Web.Administration.ServerManager" -as [type])) {
  Add-Type -Path $administrationAssembly
}

$certificateStore = $null
$certificate = $null
$serverManager = $null

try {
  $certificateStore =
    [System.Security.Cryptography.X509Certificates.X509Store]::new(
      $storeName,
      [System.Security.Cryptography.X509Certificates.StoreLocation]::LocalMachine
    )

  $openFlags =
    [System.Security.Cryptography.X509Certificates.OpenFlags]::ReadOnly -bor
    [System.Security.Cryptography.X509Certificates.OpenFlags]::OpenExistingOnly

  try {
    $certificateStore.Open($openFlags)
  }
  catch {
    throw "Could not open certificate store 'LocalMachine\$storeName': $($_.Exception.Message)"
  }

  switch ($lookupMode) {
    "Thumbprint" {
      $thumbprint = (
        ([string]$Jaws.Parameters["STEP.CertificateThumbprint"].Value) `
          -replace "[^0-9A-Fa-f]", ""
      ).ToUpperInvariant()

      if ($thumbprint -notmatch "^[0-9A-F]{40}$") {
        throw "Certificate thumbprint must contain exactly 40 hexadecimal characters."
      }

      $matches = $certificateStore.Certificates.Find(
        [System.Security.Cryptography.X509Certificates.X509FindType]::FindByThumbprint,
        $thumbprint,
        $false
      )

      if ($matches.Count -eq 0) {
        throw "Certificate '$thumbprint' was not found in LocalMachine\$storeName."
      }

      $certificate = $matches[0]
    }

    "CommonName" {
      $certificateCN =
        ([string]$Jaws.Parameters["STEP.CertificateCN"].Value).Trim()

      if ([string]::IsNullOrWhiteSpace($certificateCN)) {
        throw "Certificate common name is required."
      }

      $escapedCN =
        [System.Text.RegularExpressions.Regex]::Escape($certificateCN)

      $cnPattern = "(?:^|,\s*)CN\s*=\s*$escapedCN(?:\s*,|$)"
      $now = Get-Date

      $certificate = $certificateStore.Certificates |
        Where-Object {
          $_.Subject -match $cnPattern -and
          $_.NotBefore -le $now -and
          $_.NotAfter -gt $now -and
          $_.HasPrivateKey
        } |
        Sort-Object -Property NotAfter -Descending |
        Select-Object -First 1

      if ($null -eq $certificate) {
        throw "No valid certificate with common name '$certificateCN' and an accessible private key was found in LocalMachine\$storeName."
      }
    }

    default {
      throw "Certificate lookup mode must be Thumbprint or CommonName."
    }
  }

  if (-not $certificate.HasPrivateKey) {
    throw "Certificate '$($certificate.Thumbprint)' does not have an accessible private key."
  }

  $thumbprint = $certificate.Thumbprint.ToUpperInvariant()
  Write-Output "Using certificate thumbprint '$thumbprint' from LocalMachine\$storeName."

  $bindingInformation = "*:443:$hostName"
  $sniFlag = [Microsoft.Web.Administration.SslFlags]::Sni

  $initialSslFlags = if ($requireSni) {
    $sniFlag
  }
  else {
    [Microsoft.Web.Administration.SslFlags]::None
  }

  $serverManager = [Microsoft.Web.Administration.ServerManager]::new()
  $site = $serverManager.Sites[$siteName]

  if ($null -eq $site) {
    throw "IIS website '$siteName' was not found."
  }

  $binding = $site.Bindings |
    Where-Object {
      $_.Protocol -eq "https" -and
      $_.BindingInformation -eq $bindingInformation
    } |
    Select-Object -First 1

  $changed = $false

  if ($null -eq $binding) {
    $binding = $site.Bindings.Add(
      $bindingInformation,
      $certificate.GetCertHash(),
      $storeName,
      $initialSslFlags
    )

    $changed = $true
    Write-Output "Added HTTPS binding '$bindingInformation'."
  }
  else {
    $currentThumbprint = if ($null -ne $binding.CertificateHash) {
      [System.Convert]::ToHexString($binding.CertificateHash)
    }
    else {
      ""
    }

    if ($currentThumbprint -ne $thumbprint) {
      $binding.CertificateHash = $certificate.GetCertHash()
      $changed = $true
    }

    if ($binding.CertificateStoreName -ne $storeName) {
      $binding.CertificateStoreName = $storeName
      $changed = $true
    }

    $currentSslFlags = [int]$binding.SslFlags

    $desiredSslFlags = if ($requireSni) {
      $currentSslFlags -bor [int]$sniFlag
    }
    else {
      $currentSslFlags -band (-bnot [int]$sniFlag)
    }

    if ($desiredSslFlags -ne $currentSslFlags) {
      $binding.SslFlags =
        [Microsoft.Web.Administration.SslFlags]$desiredSslFlags

      $changed = $true
    }

    if ($changed) {
      Write-Output "Updated HTTPS binding '$bindingInformation'."
    }
    else {
      Write-Output "HTTPS binding '$bindingInformation' is already configured."
    }
  }

  if ($changed) {
    $serverManager.CommitChanges()
  }

  Write-Output "SNI required: $requireSni"
}
finally {
  if ($null -ne $serverManager) {
    $serverManager.Dispose()
  }

  if ($null -ne $certificate) {
    $certificate.Dispose()
  }

  if ($null -ne $certificateStore) {
    $certificateStore.Dispose()
  }
}
